namespace SeleneFrontend.Models;

/// <summary>
/// <c>illumination/{siteId}/ellipse.json</c> (generated by <c>pipeline/build_ellipse.py</c>, additive to the data contract):
/// terrain horizons for a grid of points around a landing site. Optional: without the file the app shows no ellipse row.
/// </summary>
public sealed class LandingEllipseData
{
    public string SiteId { get; set; } = "";
    public double Lat { get; set; }
    public double Lon { get; set; }
    public double ObserverHeightM { get; set; }
    /// <summary>Grid pitch (m): 60 m, half a pixel of the 120 m DEM.</summary>
    public double SpacingM { get; set; }
    /// <summary>Largest distance from the site covered by the grid (m).</summary>
    public double RadiusM { get; set; }
    public List<EllipsePoint> Points { get; set; } = [];
}

/// <summary>
/// One grid point. Its horizon is in its OWN azimuth frame; <see cref="AzShiftDeg"/>, <see cref="TiltDeg"/> and
/// <see cref="TiltAzDeg"/> map the site's Sun/Earth directions into it (see <c>pipeline/ellipse.py</c>).
/// </summary>
public sealed class EllipsePoint
{
    /// <summary>Offset from the site to the east (m).</summary>
    public double E { get; set; }
    /// <summary>Offset from the site to the north (m).</summary>
    public double N { get; set; }
    public double Lat { get; set; }
    public double Lon { get; set; }
    public double GroundM { get; set; }
    /// <summary>Surface slope from the 3×3 pixels of the 120 m DEM (deg); null at a data edge.</summary>
    public double? SlopeDeg { get; set; }
    public double AzShiftDeg { get; set; }
    public double TiltDeg { get; set; }
    public double TiltAzDeg { get; set; }
    /// <summary>Share of all hours in the data with any Sun (%), like <c>index.json → pctSunlit</c>.</summary>
    public double PctSunlit { get; set; }
    public double PctComms { get; set; }
    public int[] HorizonCentiDeg { get; set; } = [];

    public double DistanceM => Math.Sqrt(E * E + N * N);
}
